        let toCurrency = "AUD"

        CurrencyService.shared.getCurrencyExchangeRate(fromCurrency: fromCurrency, toCurrency: toCurrency) { exchangeRate in
            print("The exchange rate from \(fromCurrency) to \(toCurrency) is " + exchangeRate)
        }
