def min_max(list_of_numbers):
    min = list_of_numbers[0]
    max = list_of_numbers[0]
    for number in list_of_numbers:
        if number > max:
            max = number
        elif number < min:
            min = number
    return min, max

def find_most_frequent(data):
    counts = {}
    for item in data:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1
    most_frequent_item = max(counts, key=counts.get)
    return most_frequent_item

